<script setup>import{computed,onMounted,ref}from'vue';import{request}from'../api';const data=ref({engagements:[],findings:[],workpapers:[]}),busy=ref(false),message=ref('');const openFindings=computed(()=>data.value.findings.filter(x=>x.status!=='CLOSED').length);async function load(){busy.value=true;try{data.value=await request('/api/audit-ops/dashboard?organizationCode=ZH-SH')}catch(e){message.value=e.message}finally{busy.value=false}}async function create(){try{await request('/api/audit-ops/engagements',{method:'POST',body:JSON.stringify({organizationCode:'ZH-SH',projectNo:'IA-'+Date.now(),title:'供应链合规专项审计',scope:'供应商准入、采购审批、验收入库与付款',riskLevel:'HIGH',leadAuditor:'审计项目经理',plannedStart:'2026-09-01',plannedEnd:'2026-10-15'})});message.value='审计项目草稿已建立';await load()}catch(e){message.value=e.message}}onMounted(load)</script>
<template><section class="domain-head"><div><small>INTERNAL AUDIT COMMAND CENTER</small><h3>审计项目与整改闭环</h3><p>以证据链、职责分离和整改有效性为主线管理审计交付。</p></div><div><button class="ghost" @click="load">刷新</button><button @click="create">新建专项审计</button></div></section><p class="notice" v-if="message">{{message}}</p><section class="metrics"><article><span>审计项目</span><b>{{data.engagements.length}}</b><small>计划与执行全周期</small></article><article><span>待关闭发现</span><b>{{openFindings}}</b><small>整改及验证队列</small></article><article><span>审计底稿</span><b>{{data.workpapers.length}}</b><small>SHA-256 证据摘要</small></article></section><section class="layout"><article class="panel"><header><h4>项目组合</h4><span>{{busy?'读取中':'实时'}}</span></header><div class="row" v-for="x in data.engagements" :key="x.id"><div><b>{{x.title}}</b><small>{{x.projectNo}} · {{x.leadAuditor}}</small></div><em :class="x.status">{{x.status}}</em></div><div class="empty" v-if="!data.engagements.length">暂无项目，可建立首个专项审计。</div></article><article class="panel"><header><h4>高风险发现</h4><span>整改跟踪</span></header><div class="row" v-for="x in data.findings" :key="x.id"><div><b>{{x.condition}}</b><small>{{x.findingNo}} · {{x.owner}} · {{x.dueDate}}</small></div><em>{{x.status}}</em></div><div class="empty" v-if="!data.findings.length">当前没有专业审计发现。</div></article></section></template>
<style scoped>.domain-head{display:flex;justify-content:space-between;gap:24px;align-items:end;padding:26px 28px;background:#17263b;color:white;border-radius:14px}.domain-head small{letter-spacing:1.4px;color:#95b6d8}.domain-head h3{font-size:25px;margin:8px 0}.domain-head p{margin:0;color:#c7d4e3}.domain-head button{border:0;border-radius:8px;padding:10px 16px;margin-left:8px;background:#d69b3b;color:#142034;font-weight:700}.domain-head .ghost{background:#31445c;color:white}.notice{padding:10px 14px;background:#fff8e9;border-left:3px solid #d69b3b}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:16px 0}.metrics article,.panel{background:white;border:1px solid #e3e8ef;border-radius:12px;padding:18px}.metrics span,.metrics small{display:block;color:#64748b}.metrics b{font-size:28px;display:block;margin:8px 0}.layout{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel header,.row{display:flex;justify-content:space-between;align-items:center}.panel header{border-bottom:1px solid #edf0f4;padding-bottom:12px}.panel header span{color:#64748b}.row{padding:14px 0;border-bottom:1px solid #f0f2f5}.row small{display:block;color:#748092;margin-top:5px}.row em{font-style:normal;font-size:12px;background:#eef3f8;padding:5px 8px;border-radius:99px}.empty{padding:32px;text-align:center;color:#94a3b8}@media(max-width:800px){.domain-head{align-items:start;flex-direction:column}.metrics,.layout{grid-template-columns:1fr}}</style>
